-- BlockOS installer with onboarding.
-- Generated by tools/build.py from src/installer.lua: every BlockOS file is bundled below,
-- so this single program can be run from Pastebin, GitHub or a disk.

local Version = "@VERSION@"
local Files = {}
--@FILES@

local Loaded = {}
local Fresh = { ui = true }

local function Key(Path)
	return (Path:gsub("^/+", ""))
end

local function WriteFile(Path, Content)
	local Dir = fs.getDir(Path)
	if (Dir ~= "" and not fs.exists(Dir)) then
		fs.makeDir(Dir)
	end
	local Handle = fs.open(Path, "w")
	if (not Handle) then error("Cannot write " .. Path, 0) end
	Handle.write(Content)
	Handle.close()
end

local function SortedPaths()
	local List = {}
	for Path in pairs(Files) do
		table.insert(List, Path)
	end
	table.sort(List)
	return List
end

local function BackupStartup()
	if (fs.exists("startup.lua") and not fs.exists("blockos")) then
		if (fs.exists("startup.lua.bak")) then fs.delete("startup.lua.bak") end
		fs.move("startup.lua", "startup.lua.bak")
	end
end

local function InstallFiles(Progress)
	BackupStartup()
	local List = SortedPaths()
	for Index, Path in ipairs(List) do
		if (Progress) then Progress(Index - 1, #List, Path) end
		WriteFile(Path, Files[Path])
		if (Index % 6 == 0) then sleep(0) end
	end
	if (Progress) then Progress(#List, #List, "Done") end
end

local function InstallAgent()
	print("Installing the BlockOS Turtle Agent...")
	WriteFile("blockos/turtle/agent.lua", Files["blockos/turtle/agent.lua"])
	if (fs.exists("startup.lua")) then
		if (fs.exists("startup.lua.bak")) then fs.delete("startup.lua.bak") end
		fs.move("startup.lua", "startup.lua.bak")
	end
	WriteFile("startup.lua", "shell.run(\"/blockos/turtle/agent.lua\")\n")
	if (not os.getComputerLabel()) then
		os.setComputerLabel("turtle-" .. os.getComputerID())
	end
	print("Done. The agent starts on boot and shows a pairing PIN.")
	print("Rebooting in 3 seconds...")
	sleep(3)
	os.reboot()
end

local function Ask(Question, Choices)
	while (true) do
		write(Question .. " ")
		local Answer = (read() or ""):lower():sub(1, 1)
		for _, Choice in ipairs(Choices) do
			if (Answer == Choice) then return Choice end
		end
	end
end

_G.BlockOS = { Root = "/blockos", Installer = true, Version = Version }

function BlockOS.Load(Path, ...)
	local Source = Files[Key(Path)]
	local Fn, Err
	if (Source) then
		Fn, Err = load(Source, "@/" .. Key(Path), "t", _G)
	else
		Fn, Err = loadfile(Path, nil, _G)
	end
	if (not Fn) then error(Err, 2) end
	return Fn(...)
end

function BlockOS.Require(Name)
	if (Loaded[Name]) then return Loaded[Name] end
	local Module = BlockOS.Load("/blockos/lib/" .. Name .. ".lua")
	if (not Fresh[Name]) then Loaded[Name] = Module end
	return Module
end

math.randomseed(os.epoch("utc") + os.getComputerID())

term.setBackgroundColor(colors.black)
term.clear()
term.setCursorPos(1, 1)
if (term.isColor()) then term.setTextColor(colors.lime) end
print("BlockOS " .. Version .. " installer")
if (term.isColor()) then term.setTextColor(colors.white) end

if (turtle) then
	if (not term.isColor()) then
		InstallAgent()
		return
	end
	print("This is an advanced turtle.")
	print("[F] Full BlockOS desktop  [A] Turtle Agent only")
	if (Ask("Choice (f/a):", { "f", "a" }) == "a") then
		InstallAgent()
		return
	end
elseif (not term.isColor()) then
	print("BlockOS needs an Advanced Computer (gold).")
	print("Basic turtles can install the Turtle Agent instead.")
	return
end

if (fs.exists("/blockos/data/users.dat")) then
	local Installed = "unknown"
	if (fs.exists("/blockos/version.txt")) then
		local Handle = fs.open("/blockos/version.txt", "r")
		Installed = (Handle.readAll() or ""):gsub("%s+", "")
		Handle.close()
	end
	print("BlockOS " .. Installed .. " is already installed.")
	if (Ask("Update it to " .. Version .. "? Your data is kept. (y/n):", { "y", "n" }) ~= "y") then return end
	InstallFiles(function(Done, Total, Path)
		term.setCursorPos(1, select(2, term.getCursorPos()))
		term.clearLine()
		write(string.format("[%3d%%] %s", math.floor(Done / math.max(Total, 1) * 100), Path:sub(1, 40)))
	end)
	print()
	print("Updated. Rebooting...")
	sleep(1)
	os.reboot()
	return
end

local Setup = BlockOS.Load("/blockos/sys/setup.lua")
local State = Setup.Run({ Mode = "install", Version = Version, Install = InstallFiles })
if (State and State.Finished) then
	os.reboot()
end
